    def format_results(self, results: list[SemanticSearchResult], query: str = "") -> str:
        """Format search results as human-readable text."""
        if not results:
            return "No results found."

        lines = [f"Semantic search results ({len(results)}):"]
        for i, r in enumerate(results, 1):
            location = r.file_path
            if r.start_line > 0:
                location += f":{r.start_line}-{r.end_line or r.start_line}"
            lines.append(
                f"  {i}. [{r.chunk_type}] {location}"
                f" — {r.name} (score: {r.score:.3f})"
            )
            if query:
                evidence = hit_evidence(query, r)
                if evidence["matched_terms"]:
                    lines.append(
                        "     matches: " + ", ".join(evidence["matched_terms"])
                        + " (" + ", ".join(evidence["match_fields"]) + ")"
                    )
            if r.text:
                evidence = search_snippet(r, query, 120)
                preview = evidence["snippet"]
                if evidence["snippet_start_line"] is not None:
                    preview = f"snippet {evidence['snippet_start_line']}-{evidence['snippet_end_line']}: {preview}"
                if evidence["snippet_truncated"]:
                    preview += "..."
                lines.append(f"     {preview}")
        return "\n".join(lines)

